create function pos_private.report_money(n numeric) returns text language sql immutable set search_path='' as $$select 'Rp '||replace(to_char(coalesce(n,0),'FM999,999,999,999,999,990'),',','.')$$;
create function pos_private.sales_email_html(m jsonb) returns text language plpgsql immutable set search_path='' as $$declare h text;k text;v text;detail text;begin
 h:='<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily sales</title></head><body style="margin:0;padding:0;background:#f3f6f5;color:#183630;font-family:Arial,Helvetica,sans-serif"><div style="display:none;max-height:0;overflow:hidden">Your daily sales summary — '||pos_private.report_money((m->>'net_collections')::numeric)||' collected.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f3f6f5"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="600" align="center" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #e0e8e4;border-radius:16px"><tr><td style="padding:28px 24px 20px;border-bottom:1px solid #e8eeeb"><p style="margin:0 0 12px;font-size:11px;letter-spacing:2px;color:#087f6c;font-weight:bold">DAILY SALES REPORT</p><h1 style="margin:0 0 8px;font-size:23px;line-height:1.3">'||pos_private.html_escape(m->>'outlet')||'</h1><p style="margin:0;color:#6b8079;font-size:13px">'||to_char((m->>'day')::date,'DD Mon YYYY')||' · '||pos_private.html_escape(m->>'timezone')||'</p></td></tr><tr><td style="padding:20px 24px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="background:#087f6c;border-radius:12px;padding:22px;color:#ffffff"><p style="margin:0 0 8px;font-size:13px;color:#d6f1e8">NET COLLECTIONS</p><p style="margin:0;font-size:30px;line-height:1.2;font-weight:bold">'||pos_private.report_money((m->>'net_collections')::numeric)||'</p><p style="margin:8px 0 0;font-size:12px;color:#d6f1e8">Received payments minus completed refunds</p></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:12px"><tr><td width="50%" valign="top" style="padding:14px;background:#f4f8f6;border-radius:10px"><p style="margin:0 0 6px;font-size:12px;color:#6b8079">Paid orders</p><p style="margin:0;font-size:24px;font-weight:bold">'||pos_private.html_escape(m->>'bills')||'</p></td><td width="12"></td><td width="50%" valign="top" style="padding:14px;background:#f4f8f6;border-radius:10px"><p style="margin:0 0 6px;font-size:12px;color:#6b8079">Average bill</p><p style="margin:0;font-size:20px;font-weight:bold">'||pos_private.report_money(case when (m->>'bills')::numeric=0 then 0 else round((m->>'collections')::numeric/(m->>'bills')::numeric) end)||'</p></td></tr></table><h2 style="margin:24px 0 10px;font-size:15px">Sales summary</h2><table role="presentation" width="100%" cellpadding="0" cellspacing="0">';
 for k,v in select * from (values ('Net menu sales',pos_private.report_money((m->>'net_sales_before_refunds')::numeric)),('Discounts',pos_private.report_money((m->>'discount')::numeric)),('Service + tax',pos_private.report_money((m->>'service')::numeric+(m->>'tax')::numeric)),('Completed refunds',pos_private.report_money((m->>'refunds')::numeric))) x loop
 h:=h||'<tr><td style="padding:9px 0;border-bottom:1px solid #edf1ef;color:#6b8079;font-size:13px">'||k||'</td><td align="right" style="padding:9px 0;border-bottom:1px solid #edf1ef;font-size:14px;font-weight:bold">'||v||'</td></tr>';end loop;
 h:=h||'</table><h2 style="margin:22px 0 10px;font-size:15px">Payment methods</h2><table role="presentation" width="100%" cellpadding="0" cellspacing="0">';
 if m->'methods'='{}'::jsonb then h:=h||'<tr><td style="font-size:13px;color:#6b8079;padding:8px 0">No payments recorded</td></tr>';end if;
 for k,v in select key,value from jsonb_each_text(m->'methods') order by key loop h:=h||'<tr><td style="padding:8px 0;font-size:13px;color:#6b8079">'||pos_private.html_escape(case k when 'cash' then 'Cash' when 'credit_card' then 'Credit card' when 'debit_card' then 'Debit card' when 'qr' then 'QR / QRIS' when 'transfer' then 'Bank transfer' else initcap(replace(k,'_',' ')) end)||'</td><td align="right" style="padding:8px 0;font-size:14px;font-weight:bold">'||pos_private.report_money(v::numeric)||'</td></tr>';end loop;
 h:=h||'</table><p style="margin:18px 0 0;font-size:12px;color:#6b8079">Cancelled orders: '||pos_private.html_escape(m->>'cancelled_bills')||' · Voided items: '||pos_private.html_escape(m->>'voided_items')||'</p>';
 if (m->>'missing_cost_lines')::integer>0 then h:=h||'<p style="margin:12px 0 0;padding:12px;background:#fff7e5;border-radius:8px;font-size:12px;color:#8b6928;line-height:1.5">Product costs are incomplete for '||pos_private.html_escape(m->>'missing_cost_lines')||' sold lines. Gross profit is available after all costs are recorded.</p>';else h:=h||'<p style="margin:14px 0 0;font-size:12px;color:#6b8079">Recorded product costs: '||pos_private.report_money((m->>'recorded_cogs')::numeric)||'. This summary does not include operating expenses.</p>';end if;
 return h||'</td></tr><tr><td align="center" style="padding:18px 24px;border-top:1px solid #e8eeeb;font-size:11px;line-height:1.6;color:#87988f">Daily operational summary · Details in Back Office reports<br>Powered by <strong>SUMS POS</strong></td></tr></table></td></tr></table></body></html>';
end$$;
create or replace function pos_private.queue_report_internal(b uuid,d date) returns integer language plpgsql security definer set search_path='' as $$declare cfg public.pos_report_settings;m jsonb;recipient_address text;payload jsonb;html text;plain text;k text;v text;n integer:=0;row_count integer;begin
 select * into cfg from public.pos_report_settings where business_id=b;if not found then raise exception 'Configure report email first';end if;
 if not exists(select 1 from public.pos_memberships where business_id=b and user_id=cfg.configured_by and role='owner' and active) then raise exception 'Report owner access is inactive';end if;
 if not exists(select 1 from unnest(array_prepend(cfg.owner_email,cfg.extra_emails)) x where not exists(select 1 from public.pos_report_mail_jobs j where j.business_id=b and j.report_day=d and j.recipient=x)) then return 0;end if;
 m:=pos_private.daily_metrics(b,d);
 html:=pos_private.sales_email_html(m);
 plain:='Daily sales — '||(m->>'outlet')||chr(10)||to_char(d,'DD Mon YYYY')||' · '||(m->>'timezone')||chr(10)||'Net collections: '||pos_private.report_money((m->>'net_collections')::numeric)||chr(10)||'Paid orders: '||(m->>'bills')||chr(10)||'Net menu sales: '||pos_private.report_money((m->>'net_sales_before_refunds')::numeric)||chr(10)||'Discounts: '||pos_private.report_money((m->>'discount')::numeric)||chr(10)||'Service + tax: '||pos_private.report_money((m->>'service')::numeric+(m->>'tax')::numeric)||chr(10)||'Completed refunds: '||pos_private.report_money((m->>'refunds')::numeric)||chr(10)||'Payment methods:'||chr(10);
 for k,v in select key,value from jsonb_each_text(m->'methods') order by key loop plain:=plain||initcap(replace(k,'_',' '))||': '||pos_private.report_money(v::numeric)||chr(10);end loop;
 plain:=plain||'Cancelled orders: '||(m->>'cancelled_bills')||' · Voided items: '||(m->>'voided_items')||chr(10)||'Amounts exclude operating expenses. Full details are in Back Office reports.'||chr(10)||'Powered by SUMS POS';
 for recipient_address in select unnest(array_prepend(cfg.owner_email,cfg.extra_emails)) loop
  payload:=jsonb_build_object('from','SUMS POS <reports@mail.sumsstudio.id>','to',jsonb_build_array(recipient_address),'subject','Daily sales · '||(m->>'outlet')||' · '||d::text,'html',html,'text',plain);
  insert into public.pos_report_mail_jobs(business_id,report_day,recipient,payload) values(b,d,recipient_address,payload) on conflict(business_id,report_day,recipient) do nothing;get diagnostics row_count=row_count;n:=n+row_count;
 end loop;return n;
end$$;

revoke all on function pos_private.report_money(numeric),pos_private.sales_email_html(jsonb) from public,anon,authenticated;
